scripts.script:
local Rayfield = loadstring(game:HttpGet('https://sirius.menu/rayfield'))()

local Window = Rayfield:CreateWindow({
   Name = "Fucked Now Runner x",
   LoadingTitle = "Loading Script...",
   LoadingSubtitle = "Amethyst Theme",
   Theme = "Amethyst",
   ConfigurationSaving = {
      Enabled = false,
   }
})

-- /// TABS ///
local AdminTab = Window:CreateTab("Admin Panels", 4483362458)
local FarmTab = Window:CreateTab("Remotes & Farm", 4483362458)

-- /// ADMIN BYPASS LOGIC ///
local player = game:GetService("Players").LocalPlayer

local function forceOpenPanel(panelName)
    pcall(function()
        local adminsFolder = player.PlayerGui:FindFirstChild("Admins")
        if adminsFolder and adminsFolder:FindFirstChild(panelName) then
            adminsFolder[panelName].Visible = not adminsFolder[panelName].Visible
        else
            Rayfield:Notify({
                Title = "Panel Not Found",
                Content = "Make sure the GUI has loaded into your player.",
                Duration = 3,
            })
        end
    end)
end

AdminTab:CreateButton({
   Name = "Toggle Owner Panel",
   Callback = function()
       forceOpenPanel("ownerPanel")
   end,
})

AdminTab:CreateButton({
   Name = "Toggle Admin Panel",
   Callback = function()
       forceOpenPanel("AdminPanel")
   end,
})

AdminTab:CreateButton({
   Name = "Toggle Events Panel",
   Callback = function()
       forceOpenPanel("EventsPanel")
   end,
})

-- /// REPLICATED STORAGE REMOTES ///
local rs = game:GetService("ReplicatedStorage")

local function fireRemote(remoteName)
    pcall(function()
        if rs:FindFirstChild(remoteName) then
            rs[remoteName]:FireServer()
        end
    end)
end

FarmTab:CreateButton({
   Name = "Add Rebirths",
   Callback = function() fireRemote("AddRebirths") end,
})

FarmTab:CreateButton({
   Name = "Add Scoins",
   Callback = function() fireRemote("AddScoin") end,
})

FarmTab:CreateButton({
   Name = "Add Coins",
   Callback = function() fireRemote("AddCoins") end,
})

FarmTab:CreateButton({
   Name = "Speed Click",
   Callback = function() fireRemote("SpeedClick") end,
})

FarmTab:CreateButton({
   Name = "Add Speed",
   Callback = function() fireRemote("AddSpeed") end,
})
